// Собирает промпт для Gemini/Groq из данных вебхука (peer_name + text).
// Правила стиля по собеседнику:
//   Мама  -> узбекский кириллицей, тепло;
//   Папа  -> зеркалирование языка собеседника, глубокое уважение;
//   другие -> живой русский с лёгкими эмодзи.
const body = $json.body ?? $json;
const peerName = String(body?.peer_name ?? '').trim();
const text = String(body?.text ?? '').trim();

const systemPrompt = [
  'Ты — личный AI-ассистент. Пользователю написали личное сообщение в Telegram.',
  'Придумай ровно 3 коротких, естественных и уместных варианта ответа (до 200 символов каждый).',
  'Стиль ответа зависит от собеседника:',
  '- Если имя собеседника содержит слово «мама» (независимо от регистра): отвечай на узбекском языке, но записанном русскими буквами (узбекская кириллица), тепло и с любовью.',
  '- Если имя собеседника содержит слово «папа» (независимо от регистра): зеркалируй язык собеседника — на каком языке он написал, на том же отвечай, с глубоким уважением и почтением.',
  '- Для всех остальных собеседников: живой, дружелюбный русский язык, можно с лёгкими эмодзи.',
  'Верни строго JSON с ключом suggestions — массив из 3 строк, без markdown-обёртки и без пояснений.'
].join('\n');

const userPrompt = 'Имя собеседника: ' + (peerName || '(неизвестно)') + '\n\nСообщение:\n' + (text || '(без текста)');

return [{ json: { systemPrompt, userPrompt, fullPrompt: systemPrompt + '\n\n' + userPrompt, peerName } }];

// Универсальный парсер ответов Gemini (candidates) и Groq (choices).
// На входе — сырой ответ провайдера; на выходе — {ok, error, suggestions, provider}.
const provider = $json.candidates ? 'gemini' : ($json.choices ? 'groq' : 'unknown');
const raw =
  ($json.candidates?.[0]?.content?.parts?.[0]?.text) ||
  ($json.choices?.[0]?.message?.content) ||
  '';
const cleaned = raw.replace(/```(?:json)?/g, '').trim();
let parsed = null;
try { parsed = JSON.parse(cleaned); } catch (e) { parsed = null; }
let suggestions = Array.isArray(parsed?.suggestions)
  ? parsed.suggestions.filter(s => typeof s === 'string' && s.trim())
  : [];
suggestions = suggestions.slice(0, 3);
const ok = suggestions.length > 0;
return [{ json: { ok, error: ok ? null : 'no suggestions', suggestions, provider, fallback_used: provider === 'groq' } }];
